/**
 * Integration B: technical documentation search via DeepSpace `exa/search`.
 *
 * Results are restricted to a short list of reference sites and every
 * returned URL is re-checked against that list, so the panel only shows real
 * documentation links (title + URL from Exa, never generated by a model).
 */
import type { ActionHandler } from 'deepspace/worker'
import type { Env } from '../../worker'
import type { DocResult } from '../shared/types'
import { docsQuerySchema } from '../shared/validation'
import { fail, guard, invalid, isSignedIn } from './common'
import { claimIntegrationQuota } from './quota'

export const DOC_DOMAINS = [
  'developer.mozilla.org',
  'web.dev',
  'www.w3.org',
  'webaim.org',
  'www.a11yproject.com',
  'css-tricks.com',
] as const

interface ExaResult {
  title?: string | null
  url?: string
  highlights?: unknown
  text?: unknown
  summary?: unknown
}

function snippetOf(result: ExaResult): string {
  const highlight = Array.isArray(result.highlights) ? result.highlights.find((h) => typeof h === 'string') : undefined
  const raw = typeof highlight === 'string' ? highlight : typeof result.summary === 'string' ? result.summary : ''
  const clean = raw.replace(/\s+/g, ' ').trim()
  return clean.length > 240 ? `${clean.slice(0, 240)}…` : clean
}

export function toDocResults(payload: unknown): DocResult[] {
  const results = (payload as { results?: ExaResult[] } | null)?.results
  if (!Array.isArray(results)) return []
  const seen = new Set<string>()
  const docs: DocResult[] = []
  for (const result of results) {
    if (typeof result?.url !== 'string') continue
    let url: URL
    try {
      url = new URL(result.url)
    } catch {
      continue
    }
    if (url.protocol !== 'https:' || !(DOC_DOMAINS as readonly string[]).includes(url.hostname)) continue
    if (seen.has(url.href)) continue
    seen.add(url.href)
    docs.push({
      title: (result.title ?? '').trim().slice(0, 160) || url.hostname,
      url: url.href,
      domain: url.hostname,
      snippet: snippetOf(result),
    })
  }
  return docs.slice(0, 6)
}

export const searchDocs: ActionHandler<Env> = (ctx) =>
  guard('searchDocs', async () => {
    const { userId, tools } = ctx
    if (!isSignedIn(userId)) return fail('unauthenticated', 'Sign in to search documentation.')
    const parsed = docsQuerySchema.safeParse(ctx.params)
    if (!parsed.success) return invalid(parsed.error)

    if (!(await claimIntegrationQuota(tools, 'docs', userId))) {
      return fail('quota_exceeded', 'You have used today’s documentation searches. Try again tomorrow.')
    }

    const result = await tools.integration('exa/search', {
      query: parsed.data.query,
      numResults: 8,
      type: 'auto',
      includeDomains: [...DOC_DOMAINS],
      contents: { highlights: { numSentences: 2, highlightsPerUrl: 1, maxCharacters: 300 } },
    })
    if (!result.success) {
      console.error('[docs] integration failed:', result.code, result.error)
      if (result.code === 'insufficient_credits') {
        return fail('insufficient_credits', 'Documentation search is unavailable right now (the app has run out of credits).')
      }
      return fail('integration_failed', 'Documentation search did not respond. Try again in a moment.')
    }
    return { success: true, data: { results: toDocResults(result.data), query: parsed.data.query } }
  })
